package de.ostms.lc.check.service;
import de.ostms.lc.check.api.*;import de.ostms.lc.lc.repository.LetterOfCreditRepository;import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.common.PDRectangle;import org.apache.pdfbox.pdmodel.font.*;import org.springframework.stereotype.Service;import java.io.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class DocumentCheckReportService{
 private final DocumentCheckService checks;private final LetterOfCreditRepository lcs;private final de.ostms.lc.document.repository.LcDocumentRepository documents;private final de.ostms.lc.document.service.PdfPagePreviewService previews;
 public DocumentCheckReportService(DocumentCheckService c,LetterOfCreditRepository l){this(c,l,null,null);}
 @org.springframework.beans.factory.annotation.Autowired public DocumentCheckReportService(DocumentCheckService c,LetterOfCreditRepository l,de.ostms.lc.document.repository.LcDocumentRepository d,de.ostms.lc.document.service.PdfPagePreviewService p){checks=c;lcs=l;documents=d;previews=p;}
 /** Marked evidence of a decision: where it is (document, page) and, when the page can be rendered, a cut-out of the marked area. */
 record MarkedEvidence(String where,byte[] image){}
 Optional<MarkedEvidence> markedEvidence(UUID lcId,CheckResult item){
  if(item.reviewDecision()==null)return Optional.empty();
  String json;try{json=checks.decisionMark(lcId,item).orElse(null);}catch(RuntimeException e){return Optional.empty();}
  if(json==null||json.isBlank())return Optional.empty();
  try{
   var mark=new com.fasterxml.jackson.databind.ObjectMapper().readTree(json);int page=mark.path("page").asInt(1);
   var doc=documents==null?null:documents.findById(UUID.fromString(mark.path("documentId").asText())).filter(d->d.getLetterOfCredit()!=null&&lcId.equals(d.getLetterOfCredit().getId())).orElse(null);
   String where=(doc==null?"marked document":doc.getOriginalFilename())+", page "+page;
   if(doc==null||previews==null||doc.getContent()==null||!"application/pdf".equalsIgnoreCase(doc.getContentType()))return Optional.of(new MarkedEvidence(where,null));
   float pw,ph;try(var pdf=org.apache.pdfbox.Loader.loadPDF(doc.getContent())){if(page<1||page>pdf.getNumberOfPages())return Optional.of(new MarkedEvidence(where,null));var box=pdf.getPage(page-1).getMediaBox();pw=box.getWidth();ph=box.getHeight();}
   double scale=200/72.0;int left=(int)Math.round(mark.path("x").asDouble()*pw*scale),top=(int)Math.round(mark.path("y").asDouble()*ph*scale),width=(int)Math.max(1,Math.round(mark.path("w").asDouble()*pw*scale)),height=(int)Math.max(1,Math.round(mark.path("h").asDouble()*ph*scale));
   width=Math.min(width,1800);height=Math.min(height,1200);
   byte[] image=null;try{image=previews.markedCrop(doc.getContent(),new de.ostms.lc.document.service.SpatialMetadata.Field("",page,left,top,width,height,"Markierte Fundstelle","MARKED"));}catch(Exception ignored){/* the location is still reported */}
   return Optional.of(new MarkedEvidence(where,image));
  }catch(Exception e){return Optional.empty();}
 }
public Report create(UUID lcId)throws IOException{var lc=lcs.findById(lcId).orElseThrow();ReviewSummary review=checks.check(lcId);try(PDDocument pdf=new PDDocument();ByteArrayOutputStream out=new ByteArrayOutputStream()){var regular=new PDType1Font(Standard14Fonts.FontName.HELVETICA);var bold=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);PageWriter writer=new PageWriter(pdf,regular,bold);writer.title("LC DOCUMENT REVIEW REPORT");writer.field("LC reference",lc.getReference());writer.field("Generated",ZonedDateTime.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm z")));writer.field("Overall status",review.status());writer.field("Summary",review.discrepancies()+" discrepancies | "+review.warnings()+" open notes | "+review.passed()+" fulfilled");writer.line("Automatic pre-check only. Final professional review remains required.");writer.space();int index=1;for(CheckResult item:review.results()){writer.heading(index+++". "+status(item)+" - "+item.message());writer.line("Automatic assessment: "+(item.automaticSeverity()==null?"not available":item.automaticSeverity().name()));writer.line("Rule code: "+value(item.code()));writer.line("Rule: "+item.rule().id()+" | Version: "+item.rule().version()+" | Catalog: "+item.ruleCatalogVersion());writer.line("Rule basis: "+item.rule().basis());writer.line("Rule explanation: "+item.rule().explanation());writer.line("Rule limitations: "+item.rule().limitations());writer.line("LC condition / comparison basis: "+value(item.lcCondition()));writer.line("Document: "+value(item.documentName()));writer.line("Document value / text evidence: "+value(item.documentEvidence()));var marked=markedEvidence(lcId,item);writer.line("Marked evidence: "+marked.map(MarkedEvidence::where).orElse("not marked"));if(marked.isPresent()&&marked.get().image()!=null)writer.image(marked.get().image());if(item.reviewDecision()!=null){writer.line("Manual decision: "+("ACCEPTED".equals(item.reviewDecision())?"fulfilled":"discrepancy confirmed"));writer.line("Reviewed by: "+value(item.reviewedBy())+" | "+item.reviewedAt());writer.line("Decision reason: "+value(item.reviewComment()));}else{writer.line("Manual decision: pending - no professional decision recorded");}writer.space();}writer.close();pdf.save(out);return new Report("Pruefbericht-"+safe(lc.getReference())+".pdf",out.toByteArray());}}
 private String status(CheckResult r){return switch(r.severity()){case OK->"FULFILLED";case WARNING->"OPEN NOTE";case DISCREPANCY->"DISCREPANCY";};}private String value(String v){return v==null||v.isBlank()?"-":v;}private String safe(String v){return v==null?"LC":v.replaceAll("[^A-Za-z0-9._-]","_");}public record Report(String filename,byte[] content){}
 private static class PageWriter{private final PDDocument pdf;private final PDFont regular,bold;private PDPageContentStream stream;private float y;private int page;
PageWriter(PDDocument p,PDFont r,PDFont b)throws IOException{pdf=p;regular=r;bold=b;newPage();}void newPage()throws IOException{if(stream!=null){footer();stream.close();}PDPage sheet=new PDPage(PDRectangle.A4);pdf.addPage(sheet);stream=new PDPageContentStream(pdf,sheet);y=790;page++;}void title(String s)throws IOException{write(bold,18,s,50);y-=8;}void heading(String s)throws IOException{ensure(55);write(bold,11,s,50);}void field(String l,String v)throws IOException{ensure(20);write(bold,9,l+":",50);y+=14;write(regular,9,v,150);}void line(String s)throws IOException{for(String part:wrap(clean(s),95)){ensure(16);write(regular,9,part,60);}}void space(){y-=6;}void image(byte[] png)throws IOException{var img=org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject.createFromByteArray(pdf,png,"evidence");float w=img.getWidth(),h=img.getHeight(),f=Math.min(1f,Math.min(420f/w,240f/h));w*=f;h*=f;ensure(h+12);y-=h-8;stream.drawImage(img,60,y,w,h);y-=14;}void ensure(float h)throws IOException{if(y-h<55)newPage();}void write(PDFont f,float size,String s,float x)throws IOException{stream.beginText();stream.setFont(f,size);stream.newLineAtOffset(x,y);stream.showText(clean(s));stream.endText();y-=14;}void footer()throws IOException{stream.beginText();stream.setFont(regular,8);stream.newLineAtOffset(50,30);stream.showText("Corporate LC Manager | Page "+page);stream.endText();}void close()throws IOException{footer();stream.close();stream=null;}String clean(String s){return (s==null?"-":s).replace('ä','a').replace('ö','o').replace('ü','u').replace('Ä','A').replace('Ö','O').replace('Ü','U').replace("ß","ss").replaceAll("[^\\x20-\\x7E]"," ").replaceAll("\\s+"," ").trim();}List<String> wrap(String s,int max){List<String> out=new ArrayList<>();StringBuilder line=new StringBuilder();for(String word:s.split(" ")){if(line.length()>0&&line.length()+word.length()+1>max){out.add(line.toString());line.setLength(0);}if(line.length()>0)line.append(' ');line.append(word);}if(line.length()>0)out.add(line.toString());return out.isEmpty()?List.of("-"):out;}}
}
